handleOneOnOneAutoSelect:
fetch("/api/dating/1on1/matches/auto", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            source_card_id: sourceCardId,
            candidate_card_id: candidateCardId,
          }),
        })

handleOneOnOneContactCheckout:
